using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System;
using System.IO;
using System.Linq;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var sc = EditorSceneManager.GetActiveScene();
            var t = "Unity=" + Application.unityVersion + " scene=" + sc.path + " dirty=" + sc.isDirty + " playing=" + EditorApplication.isPlaying + " compiling=" + EditorApplication.isCompiling;
            File.WriteAllText("Test/Tam/investigation104-editor-before.txt", t);
            r.Log(t);
            if (EditorApplication.isPlaying || sc.isDirty)
                throw new Exception("Preserve unsaved state; clean Edit needed");
        }
    }
}

